<script setup>
import { computed,ref,watchEffect } from 'vue'
import {useRoute,RouterLink} from 'vue-router'
import {projects} from '../data/projects.js'
import ProjectCard from '../components/ProjectCard.vue'
const route=useRoute()
const project=computed(()=>projects.find(p=>p.slug===route.params.slug))
const related=computed(()=>projects.filter(p=>p.slug!==project.value?.slug&&p.categories.some(c=>project.value?.categories.includes(c))).slice(0,3))
const feedback=ref('')
watchEffect(()=>{if(project.value) document.title=`${project.value.name} · Arvak Labs`})
async function share(){const url=window.location.href;try{if(navigator.share){await navigator.share({title:project.value.name,url})}else if(navigator.clipboard){await navigator.clipboard.writeText(url);feedback.value='Link copiado!'}else{fallbackCopy(url)}}catch(e){if(e.name!=='AbortError')fallbackCopy(url)}}
function fallbackCopy(url){const field=document.createElement('textarea');field.value=url;document.body.appendChild(field);field.select();try{document.execCommand('copy');feedback.value='Link copiado!'}catch{feedback.value='Copie o endereço da página no navegador.'}field.remove()}
</script>
<template>
  <div v-if="project" class="container detail-page"><RouterLink class="breadcrumb" to="/explorar">← Voltar para projetos</RouterLink><div class="detail-hero"><div><div class="overline">{{project.categories.join(' / ')}}</div><h1>{{project.name}}<span class="accent">.</span></h1><p class="detail-lead">{{project.short}}</p><div class="detail-meta"><span class="status">{{project.status || 'Status não informado'}}</span><span v-if="project.version">Versão {{project.version}}</span><span v-if="project.updated">Atualizado em {{new Date(project.updated+'T12:00:00').toLocaleDateString('pt-BR')}}</span></div><div class="detail-actions"><a v-if="project.liveUrl" class="button primary" :href="project.liveUrl" target="_blank" rel="noopener noreferrer">Acessar aplicativo ↗</a><a v-if="project.repoUrl" class="button secondary" :href="project.repoUrl" target="_blank" rel="noopener noreferrer">Código no GitHub ↗</a><a v-if="project.docsUrl" class="button secondary" :href="project.docsUrl" target="_blank" rel="noopener noreferrer">Documentação ↗</a><button class="button quiet" type="button" @click="share">Compartilhar ↗</button></div><p v-if="feedback" class="feedback" role="status">{{feedback}}</p></div><div class="detail-visual" :class="`cover-${project.id}`"><img v-if="project.cover" :src="project.cover" :alt="`Imagem de ${project.name}`"/><span v-else aria-hidden="true">{{project.monogram}}</span></div></div>
    <div v-if="project.screenshots?.length" class="screenshots"><img v-for="image in project.screenshots" :key="image" :src="image" :alt="`Captura do projeto ${project.name}`" loading="lazy"></div>
    <div class="detail-columns"><article class="detail-prose"><div class="overline">POR DENTRO DO PROJETO</div><h2>Sobre a ideia</h2><p>{{project.description}}</p><template v-if="project.problem"><h2>O problema</h2><p>{{project.problem}}</p></template><template v-if="project.features?.length"><h2>Principais funcionalidades</h2><ul class="feature-list"><li v-for="f in project.features" :key="f">{{f}}</li></ul></template><template v-if="project.challenges?.length"><h2>Desafios técnicos</h2><ul class="feature-list"><li v-for="c in project.challenges" :key="c">{{c}}</li></ul></template><template v-if="project.learnings?.length"><h2>Aprendizados</h2><ul class="feature-list"><li v-for="l in project.learnings" :key="l">{{l}}</li></ul></template></article><aside class="detail-sidebar"><div class="side-card"><span class="overline">STACK & DETALHES</span><h3>Tecnologias</h3><div class="tags large"><span v-for="t in project.technologies" :key="t">{{t}}</span></div><hr><h3>Categorias</h3><div class="tags large"><span v-for="c in project.categories" :key="c">{{c}}</span></div></div></aside></div>
    <section v-if="related.length" class="section related"><div class="section-heading"><div><span class="overline">CONTINUE EXPLORANDO</span><h2>Você também pode gostar<span class="accent">.</span></h2></div></div><div class="project-grid"><ProjectCard v-for="p in related" :key="p.id" :project="p"/></div></section></div>
  <div v-else class="container empty-state"><h1>Projeto não encontrado.</h1><p>Esse projeto pode ter sido movido ou ainda não estar no catálogo.</p><RouterLink class="button primary" to="/explorar">Explorar projetos</RouterLink></div>
</template>
